def legacy_deliveries(apps, schema_editor):
    """Before Recibido existed, Entregado closed the order: those orders close as received, on the supplier's date and confirmed by
    nobody (received_by stays NULL). update() keeps updated_at, so no conversation jumps to the top. Confirmed deals not yet delivered
    stay as they are and wait for the supplier's Procesando."""
    SupplierRequest = apps.get_model('mall', 'SupplierRequest')
    SupplierRequest.objects.filter(status='delivered').update(status='received', received_at=F('delivered_at'))


def restore_legacy(apps, schema_editor):
    """Back to the single Entregado, losing what only the new steps knew: a received order is delivered again, Procesando and En camino go
    back to the confirmed deal, and a cancellation (MotionPartes' after dispatch) forgets its dispatch dates."""
    SupplierRequest = apps.get_model('mall', 'SupplierRequest')
    SupplierRequest.objects.filter(status='received').update(status='delivered', received_at=None, received_by=None)
    SupplierRequest.objects.filter(status__in=['processing', 'in_transit']).update(
        status='handshaked', processing_at=None, processing_by=None, in_transit_at=None, in_transit_by=None)
    SupplierRequest.objects.filter(status='cancelled').update(delivered_at=None, delivered_by=None, in_transit_at=None, in_transit_by=None,
                                                              processing_at=None, processing_by=None)


